def get_icon(name: str, color: str = "#3b82f6", size: int = 20) -> QIcon:
    """Renderiza um ícone SVG vetorial nítido no tamanho e cor especificados."""
    svg_template = SVG_ICONS.get(name)
    if not svg_template:
        return QIcon()

    if "{color}" in svg_template:
        svg_content = svg_template.format(color=color)
    else:
        svg_content = svg_template
    byte_arr = QByteArray(svg_content.encode("utf-8"))

    renderer = QSvgRenderer(byte_arr)
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)

    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()

    return QIcon(pixmap)


def export_svg_icons():
    """Gera arquivos físicos .svg na pasta assets/icons/ para uso em QSS ou recursos externos."""
    pasta = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "assets", "icons")
    os.makedirs(pasta, exist_ok=True)
    for name, svg in SVG_ICONS.items():
        caminho = os.path.join(pasta, f"{name}.svg")
        with open(caminho, "w", encoding="utf-8") as f:
            f.write(svg.format(color="#3b82f6"))


if __name__ == "__main__":
    export_svg_icons()
    print("Ícones SVG exportados com sucesso em assets/icons/")
